def average(numbers):
    if not numbers:
        raise ValueError("Cannot average an empty list")
    return sum(numbers) / len(numbers)


# Example 1: Nonempty list
values1 = [2, 4, 6, 8]
print(average(values1))  # Output: 5.0

# Example 2: Empty list handling
values2 = []
try:
    print(average(values2))
except ValueError as e:
    print(e)  # Output: Cannot average an empty list
